exercises.solution:
def check_commit(msg):
    if not msg.strip():
        return ["Empty message"]
    problems = []
    if len(msg) > 50:
        problems.append("Too long")
    if msg.endswith("."):
        problems.append("Ends with a period")
    if msg[0].islower():
        problems.append("Starts with a small letter")
    return problems

